/* eslint-disable no-underscore-dangle */

'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var dirname = require( '@stdlib/utils/dirname' );
var readJSON = require( '@stdlib/fs/read-json' ).sync;
var rootDir = require( '@stdlib/_tools/utils/root-dir' );


// MAIN //

/**
* Gets the alias prefix from the parent namespace's package.json.
*
* @private
* @param {string} scalarKernelPath - scalar kernel package path
* @returns {string} alias prefix
*
* @example
* var prefix = getAliasPrefix( '@stdlib/complex/float64/base/identity' );
* // returns 'stdlib_base_complex128_'
*
* @example
* var prefix = getAliasPrefix( '@stdlib/number/float32/base/identity' );
* // returns 'stdlib_base_float32_'
*/
function getAliasPrefix( scalarKernelPath ) {
	var parentPath;
	var pkgPath;
	var pkg;

	/* Extract parent namespace path.
	* For example, '@stdlib/math/base/special/acosd' => '@stdlib/math/base/special'
	*/
	parentPath = dirname( scalarKernelPath );

	pkgPath = resolve( rootDir(), 'lib', 'node_modules', parentPath, 'package.json' );
	pkg = readJSON( pkgPath );

	if ( pkg.__stdlib__ &&
		pkg.__stdlib__.scaffold &&
		pkg.__stdlib__.scaffold.alias_prefix ) {
		return pkg.__stdlib__.scaffold.alias_prefix;
	}
	return 'stdlib_base_';
}


// EXPORTS //

module.exports = getAliasPrefix;
